import { Suspense } from "react";
import { useTranslation } from "react-i18next";
import "./i18n";

function AppContent() {
  const { t } = useTranslation();
  const count = 3;
  return (
    <main>
      <nav>
        <a href="/">{t("nav.dashboard")}</a>
        <a href="/tasks">{t("nav.tasks")}</a>
      </nav>
      <h1>{t("greeting", { name: "Alex" })}</h1>
      <p>{t("tasks.count", { count })}</p>
      <button>{t("tasks.add")}</button>
      <label>
        <input type="checkbox" /> {t("settings.notifications")}
      </label>
    </main>
  );
}

// Gate the first paint on the catalog load — otherwise the untranslated frame
// flashes before the dictionary arrives.
export default function App() {
  return (
    <Suspense fallback={null}>
      <AppContent />
    </Suspense>
  );
}

import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import HttpBackend from "i18next-http-backend";
import LanguageDetector from "i18next-browser-languagedetector";

// Catalogs live in public/locales/{lng}/{ns}.json and are fetched at runtime.
// English is the source language; keys are authored there and synced with
// `npm run i18n:extract`.
i18n
  .use(HttpBackend)
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    fallbackLng: "en",
    // qps is the pseudo-locale from `npm run i18n:pseudo` — a dev-only
    // readiness check, never a shipped language.
    supportedLngs: ["en", "fr", "qps"],
    defaultNS: "translation",
    backend: { loadPath: "/locales/{{lng}}/{{ns}}.json" },
    detection: {
      order: ["querystring", "localStorage", "navigator"],
      lookupQuerystring: "lng",
      caches: ["localStorage"],
    },
    interpolation: { escapeValue: false }, // React already escapes
  });

export default i18n;

